import random
from celery import Celery

app = Celery("tasks", broker="memory://")
app.conf.task_always_eager = True     # run inline for this demo

class Flaky(Exception):
    pass

@app.task(bind=True, autoretry_for=(Flaky,), retry_backoff=True,
          retry_backoff_max=60, retry_kwargs={"max_retries": 5})
def fetch_rate(self, currency):
    print("attempt", self.request.retries)
    if self.request.retries < 2:
        raise Flaky("upstream timeout")
    return {"currency": currency, "rate": 1.08}

print(fetch_rate.delay("EUR").get())
# attempt 0
# attempt 1
# attempt 2
# {'currency': 'EUR', 'rate': 1.08}

