# test_tasks.py
from unittest.mock import patch
import pytest
from celery import Celery

app = Celery("t", broker="memory://")

@app.task
def add(x, y):
    return x + y

def signup(user_id):
    add.delay(user_id, 1)                 # code under test enqueues a task

def test_logic_directly():
    assert add(2, 3) == 5                 # plain function call

def test_apply_runs_locally():
    r = add.apply(args=(2, 3))
    assert r.get() == 5 and r.successful()

def test_signup_enqueues():
    with patch.object(add, "delay") as delay:
        signup(7)
    delay.assert_called_once_with(7, 1)
# $ pytest -q   ->  3 passed

import time
from celery import Celery
from celery.signals import task_prerun, task_postrun, task_failure

app = Celery("proj", broker="redis://localhost:6379/0")
_started: dict[str, float] = {}

@task_prerun.connect
def on_start(task_id=None, task=None, **kw):
    _started[task_id] = time.monotonic()

@task_postrun.connect
def on_end(task_id=None, task=None, state=None, **kw):
    took = time.monotonic() - _started.pop(task_id, time.monotonic())
    print(f"{task.name} {state} in {took:.2f}s")   # or emit a metric

@task_failure.connect
def on_failure(task_id=None, exception=None, sender=None, **kw):
    print(f"{sender.name} failed: {exception!r}")  # send to error tracker

