from celery import Celery, chord, group

app = Celery("proj", broker="memory://", backend="cache+memory://")
app.conf.task_always_eager = True        # demo inline

@app.task
def count_words(doc): return len(doc.split())

@app.task
def summarize(counts): return {"docs": len(counts), "words": sum(counts)}

docs = ["a b c", "d e", "f"]
g = group(count_words.s(d) for d in docs)
print(g.apply_async().get())                         # [3, 2, 1]

res = chord(g)(summarize.s())
print(res.get())                                     # {'docs': 3, 'words': 6}

# Real backends: the last finishing header task increments the chord
# counter to 3 and triggers summarize([...all results...]).

from datetime import datetime, timedelta, timezone
from celery import Celery

app = Celery("proj", broker="redis://localhost:6379/0")

@app.task(rate_limit="100/m", ignore_result=True)
def call_partner_api(item_id): ...

@app.task(ignore_result=True)
def enqueue_due_jobs():
    # runs every minute via beat: query rows with run_at <= now
    due = [101, 102]                    # stand-in for a DB query
    for job_id in due:
        call_partner_api.apply_async(args=(job_id,), expires=300)

# Anti-pattern for long delays: the worker holds this in memory for 3 days
# and Redis redelivers it every visibility_timeout.
# call_partner_api.apply_async(args=(7,), eta=datetime.now(timezone.utc) + timedelta(days=3))

app.conf.beat_schedule = {"due-jobs": {"task": enqueue_due_jobs.name, "schedule": 60.0}}
